const videoTopics=['All','Foundations','Networks & systems','Assessment & AppSec','Detection & response','Cloud & identity'];
function industryVideoCard(v){return `<article class="video-card industry-video" data-tone="${cardTone(v.topic)}"><button class="video-cover" data-video="${v.id}" aria-label="Play ${v.title}"><span class="video-category">${v.topic}</span><span class="play-circle">▷</span><b>${v.shortTitle||v.title}</b><small>${v.provider}</small></button><div class="video-info"><div class="eyebrow">${v.format}</div><h2>${v.title}</h2><p>${v.desc}</p><div class="tags"><span class="tag">${v.edition}</span></div><div class="video-card-links"><button class="text-link" data-video="${v.id}">Watch & study →</button><a class="text-link" href="${v.notesUrl}" target="_blank" rel="noopener noreferrer">${v.notesLabel} ↗</a></div><a class="video-practice" href="${v.practice}">Then put it into practice →</a></div></article>`;}
function watchPage(){return shell(`${heading('WATCH & LEARN','Learn from people who do the work.','University foundations, practitioner courses, and official tool tutorials. Choose a topic, watch with a question in mind, then bring the idea back to a lesson or project.')}<div class="watch-intro"><div><div class="eyebrow">YOUR WATCHING ROUTE</div><h2>Foundations → Systems → Assessment → Defense</h2><p>Begin with CS50 and Professor Messer. Build networking fluency, then choose TCM, PortSwigger, or cloud identity work to match your current stage.</p></div><a class="text-link" href="#curriculum">Follow the curriculum →</a></div><div class="curriculum-tools"><label class="screen-reader" for="video-search">Search videos or creators</label><input id="video-search" class="search" type="search" placeholder="Search videos, creators, or skills…" value="${esc(videoQuery)}"><label class="screen-reader" for="video-topic">Filter video topic</label><select id="video-topic">${videoTopics.map(t=>`<option ${videoTopic===t?'selected':''}>${t}</option>`).join('')}</select></div><p id="video-count" class="result-count" role="status"></p><div class="resource-grid" id="video-grid"></div><details class="watch-chapters"><summary>Keep learning with the full CS50 course · Five chapter shortcuts</summary><div class="chapter-shortcuts">${videos[0].chapters.map(([name,start])=>`<button class="btn small outline" data-video="full" data-start="${start}">${name} ▷</button>`).join('')}</div></details><div class="banner"><b>Watch → explain → apply.</b> Note one idea and one question, then produce the linked exercise. The original freeCodeCamp / CS50 course remains available in full. Older recordings are labeled; verify current product and tool details with the linked original sources.</div><p class="source-credit">Creator uploads and companion sources reviewed 7 November 2026. YouTube loads only when you open a video. Playback depends on the provider; every viewer includes a direct YouTube link. Free videos can have paid companion material. No affiliation or endorsement is implied.</p>`,'videos');}
function updateVideos(){const found=videos.filter(v=>(videoTopic==='All'||v.topic===videoTopic)&&`${v.title} ${v.provider} ${v.topic} ${v.desc} ${v.modules.join(' ')}`.toLowerCase().includes(videoQuery.toLowerCase()));$('#video-grid').innerHTML=found.map(industryVideoCard).join('')||'<div class="empty">No videos match. Try another topic or creator.</div>';$('#video-count').textContent=`${found.length} of ${videos.length} curated videos · Original creators · Connected to practice`;}
function lessonWatchPanel(m){const found=moduleWatch(m.id);if(!found.length)return '';return `<section class="lesson-watch"><div class="eyebrow">WATCH THE IDEA IN PRACTICE</div><h2>A different way to understand it.</h2>${found.map(v=>`<button data-video="${v.id}"><span>${icon('play')}</span><span><b>${v.shortTitle||v.title}</b><small>${v.provider}</small></span><span aria-hidden="true">↗</span></button>`).join('')}<a class="text-link" href="#videos">Explore all courses & videos →</a></section>`;}
